local config = {
  ui_story_30360401_1_dialog_content = "So... What's the matter?",
  ui_story_30360401_2_dialog_content = "<color=#e8d9bb>After darkness fell, I closed my eyes and fell into a deep sleep.</color>",
  ui_story_30360401_3_dialog_content = "But I woke up in the middle of the night to a pair of eyes shining in the dark...",
  ui_story_30360401_4_dialog_content = "I was sure that what stood before me was a beast...",
  ui_story_30360401_5_dialog_content = "You mean, a wolf was watching you last night?",
  ui_story_30360401_6_dialog_content = "Yes, I believe that it may be one of your shadow wolves.",
  ui_story_30360401_7_dialog_content = "That's impossible... I haven't used my shadow magic, nor ordered any of my shadow wolves to do so.",
  ui_story_30360401_8_dialog_content = "I know... I'm not doubting you.",
  ui_story_30360401_9_dialog_content = "But this has been going on for so many days that I have to talk to you about it.",
  ui_story_30360401_10_option_content = "Although I have no proof...",
  ui_story_30360401_11_dialog_content = "Because I could sense it.",
  ui_story_30360401_12_dialog_content = "You mean, through your psychic ability?",
  ui_story_30360401_13_dialog_content = "Well, then it might be them.",
  ui_story_30360401_14_option_content = "I'm sure it was a shadow wolf.",
  ui_story_30360401_15_dialog_content = "Is it possible for them to act without your permission? Could they be roaming free while you're resting?",
  ui_story_30360401_16_dialog_content = "I don't know... Maybe?",
  ui_story_30360401_17_dialog_content = "Hey, why did you go to PlayerName's room last night?",
  ui_story_30360401_18_dialog_content = "<color=#e8d9bb>The shadow wolves curl their ears.</color>",
  ui_story_30360401_19_dialog_content = "It seems you were right.",
  ui_story_30360401_20_dialog_content = "How do you know that?",
  ui_story_30360401_21_dialog_content = "I can only tell from their physical reactions, such as the way their ears twitched.",
  ui_story_30360401_22_dialog_content = "After all, I'm not like you. I can't talk to animals.",
  ui_story_30360401_23_dialog_content = "No, no, it's not really like that... Besides, do they count as animals...?",
  ui_story_30360401_24_dialog_content = "Anyway, can you please keep an eye on your shadow wolves? At least keep them from coming to my room and staring at me in the middle of the night.",
  ui_story_30360401_25_dialog_content = "Alright.",
  ui_story_30360401_26_dialog_content = "You are forbidden from entering PlayerName's room.",
  ui_story_30360401_27_dialog_content = "<color=#e8d9bb>The shadow wolves show no reaction.</color>",
  ui_story_30360401_28_dialog_content = "They tuned out.",
  ui_story_30360401_29_option_content = "Hold on... Why?",
  ui_story_30360401_30_dialog_content = "How should I know? They probably have their own reasons.",
  ui_story_30360401_31_dialog_content = "Does that mean that they'll keep coming to my room to stare at me in the middle of the night?",
  ui_story_30360401_32_dialog_content = "Most likely.",
  ui_story_30360401_33_dialog_content = "That's troubling... How can I sleep if so?",
  ui_story_30360401_32_option_content = "No, no... You have to convince them!",
  ui_story_30360401_35_dialog_content = "How can I persuade them?",
  ui_story_30360401_36_dialog_content = "Why are you asking me? Aren't you their master?",
  ui_story_30360401_37_dialog_content = "I haven't managed to teach them any commands other than attack. If they don't listen to me at all, there's nothing I can do.",
  ui_story_30360401_38_dialog_content = "What should I do?",
  ui_story_30360401_39_dialog_content = "Can't you connect with them psychically? Try communicating with them.",
  ui_story_30360401_40_option_content = "It's a little daunting.",
  ui_story_30360401_41_dialog_content = "How is it daunting?",
  ui_story_30360401_42_dialog_content = "They look like mysterious beasts, and they're recorded in the Colossus' database as dangerous creatures, not to mention the fact that they're born from your abilities.",
  ui_story_30360401_43_dialog_content = "Whether they can be counted as psychically viable entities is still unknown to me. I'm not confident in whether I can communicate with them.",
  ui_story_30360401_44_dialog_content = "I picked up the Shadow Wolf ability from unknown ruins. I don't even know what they are...",
  ui_story_30360401_45_dialog_content = "You can consider them as magical creatures, but to me they are just like ordinary dogs.",
  ui_story_30360401_46_option_content = "I'm sure it will be fine to just give it a try...",
  ui_story_30360401_47_dialog_content = "They look like cute dogs, though they don't look quite the same as those recorded in Soroz's database.",
  ui_story_30360401_48_dialog_content = "<color=#e8d9bb>The shadow wolves begin to bare their teeth.</color>",
  ui_story_30360401_49_dialog_content = "Be careful! Keep your distance... They're becoming restless.",
  ui_story_30360401_50_dialog_content = "Don't touch them too suddenly. Though they may be called Shadow Wolves, we still don't know where exactly these magical creatures come from.",
  ui_story_30360401_51_dialog_content = "Don't do anything to provoke them, or they may attack you.",
  ui_story_30360401_52_dialog_content = "Wait a minute. This is your ability, yet that's all you have to say about them?",
  ui_story_30360401_53_dialog_content = "I acquired this ability but I haven't studied it deeply. All I know is that I can use it.",
  ui_story_30360401_54_dialog_content = "Then I'd better keep my distance.",
  ui_story_30360401_55_dialog_content = "<color=#e8d9bb>You close your eyes again and return to darkness, blocking out external interference. Then, you begin to concentrate...</color>",
  ui_story_30360401_56_dialog_content = "Although I can use my psychic ability on them, I still cannot initiate conversation, as expected...",
  ui_story_30360401_57_dialog_content = "Wait... I'm suddenly sensing an image!",
  ui_story_30360401_58_dialog_content = "It's a shadow wolf... No, there's more than one...",
  ui_story_30360401_59_dialog_content = "That looks like Hydrad among them!",
  ui_story_30360401_60_dialog_content = "Have you been to my room, too!?",
  ui_story_30360401_61_dialog_content = "...",
  ui_story_30360401_62_dialog_content = "Say something!",
  ui_story_30360401_63_dialog_content = [[
You've answered all of my questions up till now.
Don't you feel like you're obviously culpable?]],
  ui_story_30360401_64_dialog_content = "Please help me to understand what is going on here.",
  ui_story_30360401_65_dialog_content = "Hmm... I did go to your room. So what?",
  ui_story_30360401_66_dialog_content = "You're the one behind all this and you don't even feel guilty!?",
  ui_story_30360401_67_dialog_content = "Why did you say it was impossible just now? Are you trying to fool me by blaming the shadow wolves?",
  ui_story_30360401_68_dialog_content = "Did you think you could hide the truth from me by pretending to help solve the problem?",
  ui_story_30360401_69_dialog_content = "As soon as I sensed it, I knew it!",
  ui_story_30360401_70_dialog_content = "No, I told you... It wasn't me last night. I've only been to your room once!",
  ui_story_30360401_71_dialog_content = "Can you see that, too?",
  ui_story_30360401_72_dialog_content = "Why? When did you go there?",
  ui_story_30360401_73_dialog_content = "Only on the day I first came to the Colossus. I went to observe you.",
  ui_story_30360401_74_dialog_content = "The reason is very simple. Since I decided to come along with you, I thought I should at least know what you are.",
  ui_story_30360401_75_dialog_content = "Wait... My gut is telling me that the reason they're acting of their own volition is you.",
  ui_story_30360401_76_dialog_content = "Has something been bothering you recently?",
  ui_story_30360401_77_dialog_content = "Have you heard of these words: \"The shadow is watching you\"?",
  ui_story_30360401_78_option_content = "I have.",
  ui_story_30360401_79_dialog_content = "Have these words been spreading around Umbraton? I remember that some people from Umbraton once talked about it.",
  ui_story_30360401_80_dialog_content = "Well, you should pay a little more attention to it.",
  ui_story_30360401_81_dialog_content = "If you can see the truth through the fog, I mean.",
  ui_story_30360401_82_option_content = "I have not.",
  ui_story_30360401_83_dialog_content = "Those words circulating Umbraton are more than just a mundane rumor. Go and ask more people and you will know.",
  ui_story_30360401_84_dialog_content = "So, what does this have to do with anything?",
  ui_story_30360401_85_dialog_content = "I can't describe it to you. You're the clairvoyant. You need to see it by yourself.",
  ui_story_30360401_86_dialog_content = "All I can tell you is that shadows pay attention to you because they like your scent.",
  ui_story_30360401_87_dialog_content = "Not just the shadow wolves... There will be many more to come.",
  ui_story_30360401_88_dialog_content = "Wait, do you mean... The shadow wolves will still come to my room?",
  ui_story_30360401_89_dialog_content = "And that there will be more creatures coming...",
  ui_story_30360401_90_dialog_content = "Most likely.",
  ui_story_30360401_91_dialog_content = "You'll get used to it over the next few days. The shadow wolves will soon leave once they are tired of watching you.",
  ui_story_30360401_92_dialog_content = "That won't do. It's already too much to take, and it's probably only going to get worse.",
  ui_story_30360401_93_dialog_content = "Why?",
  ui_story_30360401_94_dialog_content = "How... How do you suddenly manage to turn this conversation around!?",
  ui_story_30360401_95_dialog_content = "If those wild animals insist on watching me while I sleep, of course, I'm bound to feel frightened.",
  ui_story_30360401_96_dialog_content = "Do you see the shadow wolves as a threat to your safety?",
  ui_story_30360401_97_dialog_content = "Perhaps.",
  ui_story_30360401_98_dialog_content = "As the situation stands, even you don't know what they might do without your authorization. How can you ensure that they won't attack me?",
  ui_story_30360401_99_dialog_content = "This is a serious problem... That's why I came to ask if you could help.",
  ui_story_30360401_100_dialog_content = "They just want to take a closer look at what you are. Just think of them as curious dogs and you'll be fine.",
  ui_story_30360401_101_dialog_content = "However, since this is troubling you, I can't simply ignore it. After all, this is to some extent my fault.",
  ui_story_30360401_102_dialog_content = "From today on, I'll watch them at night. If they insist on going to your room, I'll try to stop them.",
  ui_story_30360401_103_dialog_content = "If I can't stop them, I'll come along.",
  ui_story_30360401_104_dialog_content = "Wait! Where's the logic in that?",
  ui_story_30360401_105_dialog_content = "If only the shadow wolves go to your room, you may feel threatened. Then I'll go and make sure they don't do anything to you.",
  ui_story_30360401_106_dialog_content = "We won't let anything else harm you.",
  ui_story_30360401_107_dialog_content = "Your troubles are solved. Done.",
  ui_story_30360201_X1_dialog_content = "What are you guys talking about?",
  ui_story_30360201_1_dialog_content = "What are you doing here? Didn't you go to Lumopolis!?",
  ui_story_30360201_2_dialog_content = "Hmm? I...",
  ui_story_30360201_3_dialog_content = "Brave navigator, why have you come here?",
  ui_story_30360201_4_dialog_content = "So, you're up to your old tricks again? Stay away from PlayerName!",
  ui_story_30360201_5_dialog_content = "What? You think I'd harm PlayerName?",
  ui_story_30360201_6_dialog_content = "I just want to talk to PlayerName, in front of you.",
  ui_story_30360201_7_dialog_content = "Impossible. We won't stand here and listen to your lies.",
  ui_story_30360201_8_dialog_content = "Hmm? Why shouldn't we listen to Mr. Kleken?",
  ui_story_30360201_9_dialog_content = "You'll be dragged into an abyss of deception... You think he's just joking around with you?",
  ui_story_30360201_10_dialog_content = "Well, I do like a good joke.",
  ui_story_30360201_11_dialog_content = "But isn't Kleken aligned with the Shadowlord?",
  ui_story_30360201_12_dialog_content = "Technically, the two of you are working together, no?",
  ui_story_30360201_13_dialog_content = "That's not the issue.",
  ui_story_30360201_14_dialog_content = "Remember this, you can't always believe the words of others.",
  ui_story_30360201_15_dialog_content = "If you were to be spirited away by such a charlatan in my presence, I'd never live it down.",
  ui_story_30360201_16_dialog_content = "Spirited away?",
  ui_story_30360201_17_dialog_content = "Perhaps. That's my guess, anyway.",
  ui_story_30360201_18_dialog_content = "Hmm... Suddenly putting me down, right in front of me? This is interesting.",
  ui_story_30360201_19_dialog_content = "You're still here?",
  ui_story_30360201_20_dialog_content = "And you want me to leave?",
  ui_story_30360201_21_dialog_content = "Well, this is now my section.",
  ui_story_30360201_22_dialog_content = "Fine, I'll leave.",
  ui_story_30360201_23_dialog_content = "Are things so bad between you two?",
  ui_story_30360201_24_dialog_content = "Just moderately bad.",
  ui_story_30360201_25_dialog_content = "I'm a little curious to know what's going on with you.",
  ui_story_30360201_26_dialog_content = "We just don't have very compatible personalities...",
  ui_story_30360201_27_dialog_content = "<color=#e8d9bb>The first time they saw each other in the slums, the gazes of these two filthy street urchins did not meet and both of them remained silent.</color>",
  ui_story_30360201_28_dialog_content = "<color=#e8d9bb>The second time they saw each other amid the chaos of the battlefield, their gazes did not meet and both of them remained silent.</color>",
  ui_story_30360201_29_dialog_content = "<color=#e8d9bb>The third time they saw each other, one stood at the Shadowlord's left, and the other at the Shadowlord's right.</color>",
  ui_story_30360201_30_dialog_content = "<color=#e8d9bb>One in a long robe, another in fine garments, their gazes did not meet and both of them remained silent.</color>",
  ui_story_30360201_31_dialog_content = "<color=#e8d9bb>The fourth time, the fifth time... their gazes did not meet and both of them remained silent.</color>",
  ui_story_30360201_32_dialog_content = "<color=#e8d9bb>Until...</color>",
  ui_story_30360201_33_dialog_content = "It's probably because of that one time. Let me tell you.",
  ui_story_30360201_34_dialog_content = "Don't interrupt...",
  ui_story_30360201_35_dialog_content = "Huh? Aren't you leaving?",
  ui_story_30360201_36_dialog_content = "I was just joking. Actually...",
  ui_story_30360201_37_dialog_content = "Let him go. I'll tell you.",
  ui_story_30360201_38_option_content = "Oh, Mr. Kleken, would you kindly leave first?",
  ui_story_30360201_39_dialog_content = "I feel that the shadow wolves have already bared their teeth, and this worries me...",
  ui_story_30360201_40_dialog_content = "Of course, if you insist, I will leave.",
  ui_story_30360201_41_dialog_content = "Forgive my impoliteness. Please continue.",
  ui_story_30360201_42_option_content = "Is that necessary?...",
  ui_story_30360201_43_dialog_content = "Of course, it's not necessary, my gentle hero.",
  ui_story_30360201_44_dialog_content = "<color=#e8d9bb>The shadow wolf beside Hydrad begins to snarl...</color>",
  ui_story_30360201_45_dialog_content = "Your little wolf cub looks angry...",
  ui_story_30360201_46_dialog_content = "You should get out of here before I get angry.",
  ui_story_30360201_47_dialog_content = "Don't worry, I can take a hint.",
  ui_story_30360201_48_dialog_content = "I won't make this any more awkward for PlayerName than it already is. I shall see you next time, hero.",
  ui_story_30360201_49_dialog_content = "I think he has really left this time.",
  ui_story_30360201_50_dialog_content = "You seem somewhat angry today?",
  ui_story_30360201_51_dialog_content = "Why have you come here all of a sudden? Didn't you go out on business?",
  ui_story_30360201_52_dialog_content = "Kleken asked me to come.",
  ui_story_30360201_53_dialog_content = "<size=45>That guy again!</size>",
  ui_story_30360201_54_dialog_content = "What did he say to you?",
  ui_story_30360201_55_dialog_content = "Well, he'd just say to go and take a look somewhere else on occasions.",
  ui_story_30360201_56_dialog_content = "Because he mentioned the Colossus this time, I just came to check it out.",
  ui_story_30360201_57_dialog_content = "I'm sorry... That sounds like a pretty confusing reason, doesn't it?",
  ui_story_30360201_58_dialog_content = "No... That's not the reason.",
  ui_story_30360201_59_dialog_content = "Well, let's get back to the point. So, what happened between you two?",
  ui_story_30360201_60_dialog_content = "I feel like you were recalling your past memories just now?",
  ui_story_30360201_61_dialog_content = "But it's nothing important...",
  ui_story_30360201_62_dialog_content = "<color=#e8d9bb>Until their first conversation.</color>",
  ui_story_30360201_63_dialog_content = "Looking for the Shadowlord? He may be in Lumopolis.",
  ui_story_30360201_64_dialog_content = "Are you looking for the Shadowlord? He may be in Lumopolis.",
  ui_story_30360201_65_dialog_content = "The first time I spoke to him, he lied to me.",
  ui_story_30360201_66_dialog_content = "Is that it? That's the end of the story?",
  ui_story_30360201_67_dialog_content = "If you want to say something, just spit it out. I won't mind and I can hear it.",
  ui_story_30360201_68_dialog_content = "Sorry...",
  ui_story_30360201_69_dialog_content = "Ahem... So you mean Kleken told you a lie the first time you spoke with him?",
  ui_story_30360201_70_dialog_content = "Yes.",
  ui_story_30360201_71_option_content = "So, the Shadowlord wasn't in Lumopolis that day?",
  ui_story_30360201_72_dialog_content = "I waited there for the whole day, until even the guards came.",
  ui_story_30360201_73_dialog_content = "I gave them a beating before heading back.",
  ui_story_30360201_74_dialog_content = "Later, the Shadowlord told me that he didn't ordinarily go to Lumopolis, so it was a complete lie.",
  ui_story_30360201_75_option_content = "Did you believe him?",
  ui_story_30360201_76_dialog_content = "I believed him, I went there, and I found nothing.",
  ui_story_30360201_77_dialog_content = "I see...",
  ui_story_30360201_78_dialog_content = "I also beat up the Lumo Guards, causing some trouble.",
  ui_story_30360201_79_dialog_content = "Wait... Why did you beat up the guards?",
  ui_story_30360201_80_dialog_content = "Because they were very rude to me.",
  ui_story_30360201_81_dialog_content = "He's been squatting there with his dogs all day...",
  ui_story_30360201_82_dialog_content = "I assume he's going to ask the nobles to take him in, right? So many people are doing that these days...",
  ui_story_30360201_83_dialog_content = "But bringing the dogs along as well? Now that's asking a little too much!",
  ui_story_30360201_84_dialog_content = "I just want them to shut up!",
  ui_story_30360201_85_dialog_content = "Ah, so it was the guards' fault.",
  ui_story_30360201_86_dialog_content = "About Kleken lying to you...",
  ui_story_30360201_87_option_content = "Maybe you're partly responsible...",
  ui_story_30360201_88_dialog_content = "Like... for believing such an obvious lie?",
  ui_story_30360201_89_dialog_content = "If I were to trust in you, would that be my fault?",
  ui_story_30360201_90_dialog_content = "That's not what I'm saying!",
  ui_story_30360201_91_dialog_content = "He was the one at fault!",
  ui_story_30360201_92_dialog_content = "You see, I don't usually believe anything he says, unless I sense the right feeling!",
  ui_story_30360201_93_dialog_content = "Even though that sounded rather weird.",
  ui_story_30360201_94_option_content = "It was entirely his fault!",
  ui_story_30360201_95_dialog_content = "Mr. Kleken does like to tell pointless lies.",
  ui_story_30360201_96_dialog_content = "He refers to himself as a scam artist, but also cautions people not to trust him.",
  ui_story_30360201_97_dialog_content = "So, don't believe anything he says again, and take each of his words with a grain of salt.",
  ui_story_30360201_98_dialog_content = "...",
  ui_story_30360201_99_dialog_content = "W-what is it? Your silence is hurting me...",
  ui_story_30360201_100_dialog_content = "Please forgive my silence... It's just that you've exceeded my expectations.",
  ui_story_30360201_101_dialog_content = "I initially wanted to warn you not to be taken in by his words.",
  ui_story_30360201_102_dialog_content = "It seems you're far more perceptive than I imagined.",
  ui_story_30360201_103_dialog_content = "Thank you for your concern but I don't think he'll do anything wrong to me.",
  ui_story_30360201_104_dialog_content = "Besides, I don't know whether saying such a thing would be a little meddlesome.",
  ui_story_30360201_105_dialog_content = "I don't want any conflict to exist between those who come to live aboard the Colossus.",
  ui_story_30360201_106_dialog_content = "So...",
  ui_story_30360201_107_dialog_content = "I know.",
  ui_story_30360201_108_dialog_content = "You're right and not meddlesome. No need to doubt yourself.",
  ui_story_30360201_109_dialog_content = "Wonderful. So, since we are all working and living together on the Colossus, we should try to get along well with each other in the future!",
  ui_story_30360201_110_dialog_content = "I can't do that.",
  ui_story_30360201_111_dialog_content = "Wait... I thought we just agreed?",
  ui_story_30360201_112_dialog_content = "I didn't agree to anything.",
  ui_story_30360201_113_dialog_content = "Now that I think about it, you always seem to end conversations with this kind of harsh indifference.",
  ui_story_30360201_114_dialog_content = "I'm almost getting used to it.",
  ui_story_30360201_115_dialog_content = "You must have other matters to attend to... I know I certainly do. Goodbye.",
  ui_story_30360201_116_dialog_content = "Huh!?...",
  ui_story_30360201_117_dialog_content = "What? Has he left?",
  ui_story_30360201_118_dialog_content = "\"Goodbye\", huh? Whether I like it or not, I'll end up running into you or that guy again.",
  ui_story_30360201_119_dialog_content = "Out of nowhere again!",
  ui_story_30360201_120_dialog_content = "If a relationship is meant to change, it will change naturally. If it isn't meant to, you shouldn't force it.",
  ui_story_30360201_121_dialog_content = "For example, things will never get better between me and that pest.",
  ui_story_30360201_122_dialog_content = "Before you came, I had another unfortunate conversation with him. What happened was...",
  ui_story_30360201_123_dialog_content = "Not you again, you octopus. Have you seen...",
  ui_story_30360201_124_dialog_content = "Oh, maybe you can find PlayerName in Lumopolis.",
  ui_story_30360201_125_dialog_content = "What did you say!?",
  ui_story_30360201_126_dialog_content = "What are you guys talking about?",
  ui_story_30360201_127_dialog_content = "What are you doing here? Didn't you go to Lumopolis!?",
  ui_story_30360201_128_dialog_content = "Just like how the octopus is still just as deceitful as before...",
  ui_story_30360201_129_dialog_content = "If you hadn't shown up in time, I would have gone to Lumopolis...",
  ui_story_30360601_1_dialog_content = "<color=#e8d9bb>In the shadows of an unnamed street sits a darkened warehouse full of animal cages. From behind their bars glitter countless pairs of menacing eyes.</color>",
  ui_story_30360601_2_dialog_content = "<color=#e8d9bb>And in the depths of the warehouse, separated by a tattered curtain—</color>",
  ui_story_30360601_3_dialog_content = "<color=#e8d9bb>Slap!</color>",
  ui_story_30360601_4_dialog_content = "...",
  ui_story_30360601_5_dialog_content = "Still not talking, eh? You're a tough one to break, I'll give you that.",
  ui_story_30360601_6_dialog_content = "Is this how you treat them too?",
  ui_story_30360601_7_dialog_content = "You kidding? That's valuable merchandise you're talking about! Worthless scum like you doesn't even compare!",
  ui_story_30360601_8_dialog_content = "\"Merchandise,\" huh? I see... Looks like I'll have to bring you to justice after all.",
  ui_story_30360601_9_dialog_content = "<color=#e8d9bb>Some time earlier</color>",
  ui_story_30360601_10_dialog_content = "So it really is you, Hydrad! Long time no see!",
  ui_story_30360601_11_dialog_content = "PlayerName? You couldn't have picked a worse time to show up.",
  ui_story_30360601_12_dialog_content = "Did you use your psychic abilities to find me? Never mind, I have something important to deal with right now.",
  ui_story_30360601_13_dialog_content = "What's the matter? Wow! Is that...",
  ui_story_30360601_14_dialog_content = "Yes. As you can see, it's a <color=#FFB400>wild wolf</color>.",
  ui_story_30360601_15_dialog_content = "A wild wolf? I've never seen one before... It looks kind of like your Shadow Wolves, doesn't it?",
  ui_story_30360601_16_dialog_content = "Where exactly did you come from?",
  ui_story_30360601_17_dialog_content = "Me? Well, I—",
  ui_story_30360601_18_dialog_content = "I meant the wolf.",
  ui_story_30360601_19_dialog_content = "... Wait, are you actually communicating with a wolf right now?",
  ui_story_30360601_20_dialog_content = "Of course not. Unlike you, I can't talk to animals.",
  ui_story_30360601_21_dialog_content = "<color=#e8d9bb>The wolf lets out a disheartened growl. Though its eyes glint ferociously, its muscles are too feeble to support its weakened body—</color>",
  ui_story_30360601_22_dialog_content = "These guys are very perceptive. They can discern other people's feelings, just like I can discern what they're thinking.",
  ui_story_30360601_23_dialog_content = "Wolves are pack animals, but this one is alone, wounded, and extremely wary of me.",
  ui_story_30360601_24_dialog_content = "Lone wolves don't just appear out of nowhere in Umbraton. Someone must have brought it here. Come out, Shadow Wolves.",
  ui_story_30360601_25_dialog_content = "See? You're in good company, now stop being so cautious around me.",
  ui_story_30360601_26_dialog_content = "I need you to ask it a question, PlayerName.",
  ui_story_30360601_27_option_content = "What? Me?",
  ui_story_30360601_28_dialog_content = "Yes, you. Just ask what happened to it.",
  ui_story_30360601_29_option_content = "I'll try, sure...",
  ui_story_30360601_30_dialog_content = "Come closer. There's nothing to be scared of.",
  ui_story_30360601_31_dialog_content = "This guy probably has friends around here, so make sure to pay attention to what it says.",
  ui_story_30360601_32_dialog_content = "<color=#e8d9bb>A filthy, run-down warehouse flashes through the wolf's mind, as well as countless other wolves locked in cages.</color>",
  ui_story_30360601_33_dialog_content = "<color=#e8d9bb>Aside from this, a number of even more brutal scenes come into view—</color>",
  ui_story_30360601_34_dialog_content = "H-Hydrad...",
  ui_story_30360601_35_dialog_content = "What is it? Are you okay?",
  ui_story_30360601_36_dialog_content = "Hey! Snap out of it, PlayerName!",
  ui_story_30360601_37_dialog_content = "I-I'm fine, I just saw a bunch of really awful memories all at once... Sorry if I worried you.",
  ui_story_30360601_38_dialog_content = "No, it's my fault. I shouldn't have asked you to get involved when you were just passing by.",
  ui_story_30360601_39_dialog_content = "It's fine, really! This isn't the first time this has happened to me, either...",
  ui_story_30360601_40_dialog_content = "Anyway, there are more important things to worry about! This wolf needs our help, Hydrad!",
  ui_story_30360601_41_dialog_content = "You were right. This wolf and its pack were captured and brought here against their will, but this one managed to escape.",
  ui_story_30360601_42_dialog_content = "They were being kept in a dirty warehouse somewhere. Also...",
  ui_story_30360601_43_dialog_content = "The people holding them there were terrible. They didn't care about the lives of these wolves at all.",
  ui_story_30360601_44_dialog_content = "... I have a pretty good idea what kind of people are behind this. Gangs like theirs were straightened out in the past, but some of them are trying to bring back the old days.",
  ui_story_30360601_45_dialog_content = "And unfortunately, there will always be rich people with poor tastes to fund their operations.",
  ui_story_30360601_46_dialog_content = "I won't let them get away with this.",
  ui_story_30360601_47_dialog_content = "What are you planning to do, Hydrad?",
  ui_story_30360601_48_dialog_content = "You said you saw a bunch of awful memories just now, right? That tells me there's no time to waste if I want to save their lives.",
  ui_story_30360601_49_dialog_content = "Alright wolf, listen up. If you want to rescue your friends, then you'll have to work with me.",
  ui_story_30360601_50_dialog_content = "Tell it to follow me so that I can help it.",
  ui_story_30360601_51_dialog_content = "Just leave it to me.",
  ui_story_30360601_52_dialog_content = "Now I just have to change. Give me a minute.",
  ui_story_30360601_53_dialog_content = "Hydrad? He left so quickly... Does he already have a plan?",
  ui_story_30360601_54_dialog_content = "<color=#e8d9bb>Shortly afterward—</color>",
  ui_story_30360601_55_dialog_content = "I'm back, now what do you think?",
  ui_story_30360601_56_dialog_content = "I look just like a brainless rich guy now, right?",
  ui_story_30360601_57_dialog_content = "Hydrad, you...",
  ui_story_30360601_58_dialog_content = "You look so cool now! Er—I mean even cooler than before! In any case, it's completely different than your usual style.",
  ui_story_30360601_59_dialog_content = "(I'm not sure he really fits the bill of a \"brainless rich guy,\" but this should do as a disguise.)",
  ui_story_30360601_60_dialog_content = "With just a few finishing touches, I'll make it look like I'm this wolf's owner...",
  ui_story_30360601_61_dialog_content = "There. Once they see me walking around the streets with it, I'm sure those hyenas will come crawling out.",
  ui_story_30360601_62_dialog_content = "While I'm doing that, I need you to sense the location of this wolf's pack, PlayerName.",
  ui_story_30360601_63_dialog_content = "I don't want to expose you to any danger, but sensing the area shouldn't be a problem, right?",
  ui_story_30360601_64_dialog_content = "If you see me going somewhere with another person, alert the Shadowlord immediately.",
  ui_story_30360601_65_dialog_content = "These guys think they can hide from the shadows, but with your help, we'll definitely root them out.",
  ui_story_30360601_66_dialog_content = "I promise I'll do my best, Hydrad.",
  ui_story_30360601_67_dialog_content = "Wait, what are you—hey!",
  ui_story_30360601_68_dialog_content = "There. You don't come across as a threat anyway, so just hide your face with your hat, and no one will notice you.",
  ui_story_30360601_69_dialog_content = "I'm heading out. The rest is in your hands now.",
  ui_story_30360601_70_dialog_content = "O-Okay! Don't let Hydrad down, don't let Hydrad down, don't let—",
  ui_story_30360601_71_dialog_content = "What are you muttering about over there?",
  ui_story_30360601_72_dialog_content = "Never mind, it's time to go.",
  ui_story_30360601_73_dialog_content = "You've been through hell, haven't you?",
  ui_story_30360601_74_dialog_content = "Awooo—",
  ui_story_30360601_75_dialog_content = "Just bear with it for a little longer. You'll get your revenge soon enough.",
  ui_story_30360601_76_dialog_content = "<color=#e8d9bb>A while later—</color>",
  ui_story_30360601_77_dialog_content = "A live wolf, eh? That's some pet you got there, pal.",
  ui_story_30360601_78_dialog_content = "Yeah? What's it to you?",
  ui_story_30360601_79_dialog_content = "No need to be rude, friend! I can tell you've got good taste, so can I interest you in some of our newest arrivals?",
  ui_story_30360601_80_dialog_content = "Got any solid-colored ones? Their coats better be glossy too.",
  ui_story_30360601_81_dialog_content = "I was right—you do know your stuff! We have all of that and more, my friend!",
  ui_story_30360601_82_dialog_content = "Our best specimens have coats as shiny as oil, and they're as fierce as they come!",
  ui_story_30360601_83_dialog_content = "As soon as you see them, you'll know they're the perfect fighting wolves. They only look that way because of how strong they are!",
  ui_story_30360601_84_dialog_content = "Aren't your people worried about the Shadowlord?",
  ui_story_30360601_85_dialog_content = "Those jerks in Lumopolis are too chicken to come down here just to buy wild animals, so who exactly are your customers?",
  ui_story_30360601_86_dialog_content = "Hahaha, you're asking a whole lot of questions there, friend!",
  ui_story_30360601_87_dialog_content = "The only way to smuggle these wolves into this town without alerting the Umbraton Guild was by sedating them the entire way.",
  ui_story_30360601_88_dialog_content = "Heh, that means they haven't eaten in days, right? That's not going to do their shiny coats any favors.",
  ui_story_30360601_89_dialog_content = "Hey pal... Who exactly are you?",
  ui_story_30360601_90_dialog_content = "Just someone who works in a similar field and takes an interest in your little operation, that's all.",
  ui_story_30360601_91_dialog_content = "So you're not planning to buy any of our wolves?",
  ui_story_30360601_92_dialog_content = "No thanks. I already have plenty.",
  ui_story_30360601_93_dialog_content = "Tsk, trying to cut into our business, eh? Who do you think you're talking to, punk?",
  ui_story_30360601_94_dialog_content = "It's always better to share the wealth, don't you think?",
  ui_story_30360601_95_dialog_content = "Hear that, boys? Looks like we got a real comedian over here!",
  ui_story_30360601_96_dialog_content = "You picked the wrong people to mess with today, kid. Now tell me who you work for!",
  ui_story_30360601_97_dialog_content = "It's hard enough to do business in Umbraton. With people like you, how are we supposed to make it out here?",
  ui_story_30360601_98_dialog_content = "Am I supposed to care?",
  ui_story_30360601_99_dialog_content = "Surround him! If you don't want to get hurt, then I suggest you come along quietly.",
  ui_story_30360601_100_dialog_content = "You don't wanna die, do you?",
  ui_story_30360601_101_dialog_content = "... Alright then.",
  ui_story_30360601_102_dialog_content = "<color=#e8d9bb>The smugglers imprison Hydrad in their warehouse, where he remains for a painfully long time.</color>",
  ui_story_30360601_103_dialog_content = "You're tougher than you look, kid. Even after this kind of beating, you're still not willing to give up your friends?",
  ui_story_30360601_104_dialog_content = "Who the heck do you think you are, picking a fight with us on our turf...",
  ui_story_30360601_105_dialog_content = "Boss, look what we found when we took off his wolf's collar! It's the same one that escaped earlier!",
  ui_story_30360601_106_dialog_content = "Damn it, I knew finding this guy on the street was too good to be true!",
  ui_story_30360601_107_dialog_content = "Is this all of you? There aren't many wolves in here either... Is this really all of your \"merchandise\" too?",
  ui_story_30360601_108_dialog_content = "If so, I suggest you give up before my friend decides to show up.",
  ui_story_30360601_109_dialog_content = "You got a death wish, pal? You should know, the <color=#FFB400>Spearows</color> let us run our operation on their turf, and—",
  ui_story_30360601_110_dialog_content = "Quiet, you idiot! We're supposed to be interrogating him!",
  ui_story_30360601_111_dialog_content = "Damn it, then it looks like we'll have to stop playing around.",
  ui_story_30360601_112_dialog_content = "Save it. I'm nothing like you buffoons.",
  ui_story_30360601_113_dialog_content = "That's because I trust that guy... my friend, that is.",
  ui_story_30360601_114_dialog_content = "What's going on?",
  ui_story_30360601_115_dialog_content = "We're screwed, boss! The Shadowlord's here, and so are his people...",
  ui_story_30360601_116_dialog_content = "Wh-What?",
  ui_story_30360601_117_dialog_content = "Heh, took them long enough.",
  ui_story_30360601_118_dialog_content = "Forget this guy, boss! We can still escape through the back door!",
  ui_story_30360601_119_dialog_content = "Not a chance.",
  ui_story_30360601_120_dialog_content = "I'm sick of waiting—come out, Shadow Wolves!",
  ui_story_30360601_121_dialog_content = "Where'd these things come from?",
  ui_story_30360601_122_dialog_content = "Look out, boss! The kid managed to break free!",
  ui_story_30360601_123_dialog_content = "Now it's time for a lesson in pain—and the <color=#FFB400>wolves</color> are gonna teach it to you!",
  ui_story_30360601_124_dialog_content = "S-Stay back!",
  ui_story_30360601_125_dialog_content = "Boss!",
  ui_story_30360601_126_dialog_content = "I'd better end this before PlayerName gets here. I don't want him to see what's about to happen.",
  ui_story_30360601_127_dialog_content = "<color=#e8d9bb>Some time later.</color>",
  ui_story_30360601_128_dialog_content = "Thanks again for your help.",
  ui_story_30360601_129_option_content = "Don't mention it. I didn't even make it inside before they told me it was already over.",
  ui_story_30360601_130_dialog_content = "Really? That's good.",
  ui_story_30360601_131_option_content = "I don't know, it just feels like I didn't do very much.",
  ui_story_30360601_132_dialog_content = "Without you, this plan would never have worked.",
  ui_story_30360601_133_dialog_content = "They had numbers, as well as an escape route.",
  ui_story_30360601_134_dialog_content = "Because you led the Shadowlord here, we were able to trap them all in one place.",
  ui_story_30360601_135_dialog_content = "Oh, heheh... I'm pretty sure you're just flattering me, but I'm glad I could help!",
  ui_story_30360601_136_dialog_content = "No, you're definitely worthy of my trust. In fact, your shadow's presence matches me even better now.",
  ui_story_30360601_137_dialog_content = "By the way, that wolf from before was reunited with its pack, and they'll be shipped back to their home soon.",
  ui_story_30360601_138_dialog_content = "After all, it's always better for pack animals to stick together.",
  ui_story_30360601_139_dialog_content = "That goes for you too, Hydrad. You and the Shadowlord make an excellent team!",
  ui_story_30360601_140_dialog_content = "... Anyway, I wonder what'll happen to the rest of the Spearows who were in on this smuggling ring.",
  ui_story_30360601_141_dialog_content = "That stinking octopus is in charge of dealing with them, so who knows when things will get done?",
  ui_story_30360601_142_dialog_content = "But it doesn't matter now. Come on, let's go.",
  ui_story_30360601_143_dialog_content = "Huh? Where are we going?",
  ui_story_30360601_144_dialog_content = "You were doing something before we ran into each other, weren't you? I was too busy with this wolf business to hear you out.",
  ui_story_30360601_145_dialog_content = "You helped me, so now it's my turn to help you.",
  ui_story_30360601_146_dialog_content = "Now let's go. Whatever it is you need to do, I'll be there to lend a hand.",
  ui_story_30360601_147_dialog_content = "So what's the plan?"
}
return config
